-- V11: local users and ended sessions (PO decision Q-47, decision 1.1, Administration -> Access part 1,
-- docs/design/PO_DECISION_RECORD_2026_11_02_Q47_ADMIN_SECTION.md).
--
-- 1. local_user: an account a security_admin creates on the screen, beside the directory and the break-glass account
--    (which stays in local_account, unchanged). The password is a BCrypt hash only; the initial and every reset
--    password is generated by the control plane, shown once to the administrator and must be changed at the next sign-in
--    (must_change_password). A local user is disabled, never deleted. The ledger names the row by the login name's
--    pseudonym (subject_fingerprint), never by the login name, which identifies a person (AGENTS.md 4.2, 4.14).
-- 2. session_end: an administrator ended another person's session; one append-only row per end, ledgered with the
--    administrator as the ledger's actor (checked here) and the administrator's reason.
-- 3. login_record accepts the source 'local_user'.

CREATE TABLE local_user (
    login_name            text        PRIMARY KEY CHECK (login_name ~ '^[a-z][a-z0-9._-]{2,31}$'
                                                         AND login_name <> 'breakglass'),
    subject_fingerprint   text        NOT NULL UNIQUE CHECK (subject_fingerprint ~ '^USR-[0-9a-f]{10}$'),
    display_name          text        NOT NULL CHECK (length(btrim(display_name)) BETWEEN 1 AND 128
                                                      AND display_name !~ '[[:cntrl:]]'),
    -- A whole BCrypt hash of cost 12 or more (PR 48 review D-07), never a shorter or weaker string.
    password_hash         text        NOT NULL CHECK (password_hash ~ '^\$2[aby]\$(1[2-9]|[23][0-9])\$[./A-Za-z0-9]{53}$'),
    -- The masked role is an exclusive session mode (MASKING_AND_PRIVACY B1): never combined with another role.
    roles                 text[]      NOT NULL CHECK (cardinality(roles) BETWEEN 1 AND 4
                                          AND roles <@ ARRAY['security_admin', 'privacy_officer', 'viewer',
                                                             'replay_viewer']::text[]
                                          AND (NOT 'replay_viewer' = ANY (roles) OR cardinality(roles) = 1)),
    enabled               boolean     NOT NULL DEFAULT true,
    must_change_password  boolean     NOT NULL DEFAULT true,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),
    password_changed_at   timestamptz,
    -- A password the user has not set themself is a generated one, which must be changed.
    CHECK (must_change_password OR password_changed_at IS NOT NULL)
);

-- The login name and its pseudonym never change; a row is never deleted (the ledger keeps naming it). A new user starts
-- with a generated password that must be changed; the change mark is cleared only together with a new hash and its
-- time, and the time of the last own change is never cleared (PR 48 review D-07).
CREATE FUNCTION rwsafe_local_user_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'LOCAL_USER_KEPT: a local user is disabled, never deleted'
            USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NOT NEW.must_change_password OR NEW.password_changed_at IS NOT NULL THEN
            RAISE EXCEPTION 'LOCAL_USER_PASSWORD_STATE: a new user starts with a generated password to change'
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.must_change_password AND NOT NEW.must_change_password
            AND (NEW.password_hash IS NOT DISTINCT FROM OLD.password_hash OR NEW.password_changed_at IS NULL
                 OR NEW.password_changed_at IS NOT DISTINCT FROM OLD.password_changed_at) THEN
        RAISE EXCEPTION 'LOCAL_USER_PASSWORD_STATE: the change mark is cleared only by a new password and its time'
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.password_changed_at IS NOT NULL AND NEW.password_changed_at IS NULL THEN
        RAISE EXCEPTION 'LOCAL_USER_PASSWORD_STATE: the time of the last own password change is never cleared'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.login_name IS DISTINCT FROM OLD.login_name
            OR NEW.subject_fingerprint IS DISTINCT FROM OLD.subject_fingerprint
            OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'LOCAL_USER_IDENTITY_FIXED: the login name, its pseudonym and the creation time never change'
            USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER local_user_guard BEFORE INSERT OR UPDATE OR DELETE ON local_user
    FOR EACH ROW EXECUTE FUNCTION rwsafe_local_user_guard();
CREATE TRIGGER local_user_audit AFTER INSERT OR UPDATE ON local_user
    FOR EACH ROW EXECUTE FUNCTION rwsafe_audit_row('subject_fingerprint');
-- A truncate bypasses row triggers, so it is refused outright.
CREATE TRIGGER local_user_no_truncate BEFORE TRUNCATE ON local_user
    FOR EACH STATEMENT EXECUTE FUNCTION rwsafe_audit_append_only();

CREATE TABLE session_end (
    end_id               bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    ended_at             timestamptz NOT NULL DEFAULT now(),
    -- The pseudonym of the person whose session ended.
    subject_fingerprint  text        NOT NULL CHECK (subject_fingerprint ~ '^USR-[0-9a-f]{10}$'),
    -- The administrator who ended it: the ledger's actor (checked below).
    ended_by             text        NOT NULL CHECK (ended_by ~ '^USR-[0-9a-f]{10}$'),
    source               text        NOT NULL CHECK (source IN ('ldap', 'local', 'local_user'))
);

CREATE FUNCTION rwsafe_session_end_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.ended_by IS DISTINCT FROM nullif(btrim(current_setting('app.actor_fingerprint', true)), '') THEN
        RAISE EXCEPTION 'SESSION_END_ACTOR: the ledger actor is the administrator who ended the session'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER session_end_guard BEFORE INSERT ON session_end
    FOR EACH ROW EXECUTE FUNCTION rwsafe_session_end_guard();
CREATE TRIGGER session_end_audit AFTER INSERT ON session_end
    FOR EACH ROW EXECUTE FUNCTION rwsafe_audit_row('subject_fingerprint');
CREATE TRIGGER session_end_no_update_or_delete BEFORE UPDATE OR DELETE ON session_end
    FOR EACH ROW EXECUTE FUNCTION rwsafe_audit_append_only();
CREATE TRIGGER session_end_no_truncate BEFORE TRUNCATE ON session_end
    FOR EACH STATEMENT EXECUTE FUNCTION rwsafe_audit_append_only();

ALTER TABLE login_record DROP CONSTRAINT login_record_source_check;
ALTER TABLE login_record ADD CONSTRAINT login_record_source_check
    CHECK (source IN ('ldap', 'local', 'local_user'));
